  export const settings = {
    dots: true,
    infinite: false,
    speed: 500,
    slidesToShow: 3,
    slidesToScroll: 1,
    autoplay: false,
    arrows: true,
    centerMode: false,
    variableWidth: false,
    responsive: [
      {
        breakpoint: 1200, // Large screens
        settings: {
          slidesToShow: 3,
          slidesToScroll: 1,
          centerPadding: '20px'
        }
      },
      {
        breakpoint: 992, // Medium screens (tablets)
        settings: {
          slidesToShow: 2,
          slidesToScroll: 1,
          centerPadding: '15px'
        }
      },
      {
        breakpoint: 768, // Small screens (mobile landscape)
        settings: {
          slidesToShow: 2,
          slidesToScroll: 1,
          centerPadding: '10px'
        }
      },
      {
        breakpoint: 576, // Extra small screens (mobile portrait)
        settings: {
          slidesToShow: 1,
          slidesToScroll: 1,
          centerMode: true,
          centerPadding: '40px'
        }
      },
      {
        breakpoint: 480, // Very small screens
        settings: {
          slidesToShow: 1,
          slidesToScroll: 1,
          centerMode: true,
          centerPadding: '20px'
        }
      }
    ]
  };