import { Card } from "@mui/material";
import React from "react";
import './CustomCard.css'
const CustomCard = ({ Children, large, small }) => {
  // return (
    
  //      <Card
  //     className="card"
  //     sx={{
  //       width: large ? 200 : "100%",
  //       maxWidth: large ? 400 : 380,
  //       height: small ? 280 : 320,
  //       backgroundColor: "#212529",
  //       border: "1px solid #22eff1",
  //       marginTop: large ? 0 : 5,
  //       margin: '0 8px', // Consistent margin for spacing
  //       boxSizing: 'border-box',
  //       '@media (max-width: 768px)': {
  //         margin: '0 6px',
  //         maxWidth: 390,
  //       },
  //       '@media (max-width: 480px)': {
  //         margin: '0 4px',
  //         maxWidth: '95%',
  //       }
  //     }}
  //   >
  //     {Children}
  //   </Card>
  // );

return (
  <Card
    className="card"
    sx={{
      width: large ? 200 : "100%",
      maxWidth: large ? 400 : 380,
      height: small ? 320 : 320, // Increased height for small cards
      minHeight: small ? 320 : 320, // Added minHeight to ensure content fits
      backgroundColor: "#212529",
      border: "1px solid #22eff1",
      marginTop: large ? 0 : 5,
      margin: '0 8px',
      boxSizing: 'border-box',
      
      // iPad specific adjustments
      '@media (min-width: 768px) and (max-width: 1024px)': {
        height: small ? 340 : 340, // Taller on iPad
        minHeight: 340,
        maxWidth: 300,
        margin: '0 6px',
      },
      
      '@media (max-width: 768px)': {
        margin: '0 6px',
        maxWidth: 390,
        height: small ? 330 : 330, // Slightly taller for mobile
        minHeight: 330,
      },
      
      '@media (max-width: 480px)': {
        margin: '0 4px',
        maxWidth: '95%',
        height: small ? 320 : 320,
        minHeight: 320,
      }
    }}
  >
    {Children}
  </Card>
);

};
export default CustomCard;
