import { Button, TextField } from "@mui/material";
import React from "react";
import CustomCard from "./CustomCard";
import StyledButton from "./StyledButton";
import { useDispatch, useSelector } from "react-redux";
import { addProduct, onRefreshClick, onShowAddProducts } from "../redux/Slice";
import RefreshIcon from "@mui/icons-material/Refresh";
const intialState = () => {
  return {
    openAddModal: false,
    productName: "",
    price: "",
    stock: "",
    errors: {
      productError: "",
      quantityError: "",
      stockError: "",
      isStockError: false,
      isQuantityError: false,
      isProductError: false,
    },
  };
};

const AddProductsComponent = () => {
  const [state, setState] = React.useState(intialState());
  const { price, productName, stock, errors } = state;
  const { productError, quantityError, isProductError, isQuantityError, stockError, isStockError } =
    errors;
  const { showAddProducts } = useSelector((state) => state.products);

  const dispatch = useDispatch();
  let currentID = 4;

  const getNextSequentialID = () => {
    const nextID = currentID;
    currentID += 1;
    return nextID;
  };

  const onHandleOpenCard = () => {
    dispatch(onShowAddProducts());
  };
  const onHanldeChange = (e) => {
    const { name, value, } = e.target;
    setState((prev) => ({
      ...prev,
      [name]: value,
      errors: {
        productError: "",
        isError: false,
      },
    }));
  };
  const handleAddProduct = () => {
    if (productName.trim() === "" || price.trim() === "" || stock.trim() === "") {
      if (productName.trim() === "") {
        console.log("hello");
        setState((prev) => ({
          ...prev,
          errors: {
            productError: "Please enter Product Name.",
            isProductError: true,
          },
        }));
      } else if (price.trim() === "") {
        setState((prev) => ({
          ...prev,
          errors: {
            quantityError: "Please enter the quantity.",
            isQuantityError: true,
          },
        }));
      } else if (stock.trim() === "") {
        setState((prev) => ({
          ...prev,
          errors: {
            stockError: "Please enter the stock",
            isStockError: true
          }
        }))
      }
    } else {
      const newID = getNextSequentialID();

      const newProduct = {
        id: newID,
        name: productName,
        price: parseFloat(price),
        totalPrice: parseFloat(0),
        totalStock: parseFloat(stock),
        quantity: 0,
      };
      console.log(newProduct);
      dispatch(addProduct(newProduct));
      setState((prev) => ({
        ...prev,
        price: "",
        productName: "",
        stock: ""
      }));
    }
  };
  const onHanldeRefresh = () => {
    dispatch(onRefreshClick());
  };
return (
    <>
      <div style={{ display: "flex", gap: "10px", marginBottom: "15px", flexWrap: "wrap" }}>
        <StyledButton
          small
          children={<RefreshIcon />}
          onClick={onHanldeRefresh}
        />
        <StyledButton children={"Add Products"} onClick={onHandleOpenCard} />
      </div>

      {showAddProducts && (
        <CustomCard
          large
          Children={
            <div
              style={{
                height: "auto",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "flex-start",
                padding: "20px",
              }}
            >
              <div 
                style={{
                  display: "flex",
                  flexDirection: "column",
                  gap: "15px",
                  width: "100%",
                  maxWidth: "300px",
                }}
              >
                <TextField
                  sx={{
                    color: "white",
                    width: "100%",
                    fieldset: { borderColor: "#89c0ee", borderWidth: 0.1 },
                    input: { color: "white" },
                  }}
                  placeholder="Product Name"
                  type="text"
                  value={productName}
                  onChange={onHanldeChange}
                  name="productName"
                  helperText={productError}
                  error={isProductError}
                />
                
                <TextField
                  sx={{
                    color: "white",
                    width: "100%",
                    fieldset: { borderColor: "#89c0ee" },
                    input: { color: "white" },
                  }}
                  placeholder="Price"
                  type="number"
                  name="price"
                  value={price}
                  onChange={onHanldeChange}
                  helperText={quantityError}
                  inputProps={{ min: 0 }}
                  error={isQuantityError}
                  onKeyDown={(e) => {
                    if (e.key === '-' || e.key === 'e' || e.key === '+') {
                      e.preventDefault();
                    }
                  }}
                />

                <TextField
                  sx={{
                    color: "white",
                    width: "100%",
                    fieldset: { borderColor: "#89c0ee" },
                    input: { color: "white" },
                  }}
                  placeholder="Total Stock"
                  type="number"
                  name="stock"
                  value={stock}
                  onChange={onHanldeChange}
                  helperText={stockError}
                  error={isStockError}
                  inputProps={{ min: 0 }}
                  onKeyDown={(e) => {
                    if (e.key === '-' || e.key === 'e' || e.key === '+') {
                      e.preventDefault();
                    }
                  }}
                />

                <Button
                  style={{
                    color: "black",
                    width: "100%",
                    backgroundColor: "aqua",
                    fontWeight: "500",
                    padding: "10px",
                  }}
                  onClick={handleAddProduct}
                >
                  ADD ITEMS
                </Button>
              </div>
            </div>
          }
        />
      )}
    </>
  );
};

export default AddProductsComponent;
