


import {
  Box,
  MeshWobbleMaterial,
  QuadraticBezierLine,
  Text,
} from "@react-three/drei";
import { extend, useFrame, useLoader } from "@react-three/fiber";
import * as THREE from "three";
import React, { useLayoutEffect, useRef, useState } from "react";
import { a } from "@react-spring/three";
import { TextGeometry } from "three/examples/jsm/geometries/TextGeometry";
import img from ".././../textures/newTexture1.jpg";
extend({ TextGeometry });

const generateRandomHash = (data = "") => {
  if (data != "") {
    const str = typeof data === "string" ? data : JSON.stringify(data);
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = (hash << 5) - hash + char;
      hash |= 0;
    }
    return "0000" + Math.abs(hash).toString(16);
  }
  return "0000" + Math.random().toString(16).slice(2, 14);
};
const generateDeterministicHash = (obj) => {
  if (!obj) return "0000" + Math.random().toString(16).slice(2, 14);

  // Helper to sort object keys recursively
  const sortObject = (input) => {
    if (typeof input !== "object" || input === null) return input;
    if (Array.isArray(input)) return input.map(sortObject);
    return Object.keys(input)
      .sort()
      .reduce((acc, key) => {
        acc[key] = sortObject(input[key]);
        return acc;
      }, {});
  };

  const sortedObj = sortObject(obj);
  const str = JSON.stringify(sortedObj);

  // Simple numeric hash function
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash |= 0; // Convert to 32-bit integer
  }

  return "0000" + Math.abs(hash).toString(16);
};

const generateRandomTimestamp = () => {
  const now = new Date();
  const randomMinutes = Math.floor(Math.random() * 60);
  const timestamp = new Date(now - randomMinutes * 60000);
  return timestamp.toISOString();
};

const Line = ({ texture, item, type }) => {
  const planeRef = useRef();
  const [isVisible, setIsVisible] = useState(true);
  const [progress, setProgress] = useState(0);

  const connectingStartingPoint = (type) => {
    let startingPoint = [];
    switch (type) {
      case "left":
        if (item.index === 5) return [0, 0.6, 0];
        else if (item.index > 5) return [0.6, 0, 0];
        else return [-0.7, 0, 0];
      case "right":
        if (item.index === 4) return [0, -0.6, 0];
        else if (item.index < 4) return [0.6, 0, 0];
        else if (item.index >= 5 && item.index < 9) return [-0.6, 0, 0];
        break;
      default:
        break;
    }
  };

  const connectingEndingPoint = (type) => {
    let endingPoint = [];
    switch (type) {
      case "left":
        if (item.index === 5) return [0, 0.1, 0];
        else if (item.index > 5) return [0.1, 0, 0];
        else return [-0.05, 0, 0];
      case "right":
        if (item.index === 4) return [0, -0.1, 0];
        else if (item.index < 4) return [0.1, 0, 0];
        else if (item.index >= 5 && item.index < 9) return [-0.1, 0, 0];
        break;
      default:
        break;
    }
  };

  const startPoint = connectingStartingPoint(type);
  const endPoint = connectingEndingPoint(type);

  useFrame((_, delta) => {
    if (progress < 1) {
      setProgress((p) => Math.min(1, p + delta * 0.5));
    }

    if (type === "left" && isVisible) {
      if (item.index === 5) planeRef.current.position.y += 0.05;
      else planeRef.current.position.x += 0.05;
    }
    if (type === "right" && isVisible) {
      if (item.index === 4) planeRef.current.position.y -= 0.05;
      else if (item.index < 4) planeRef.current.position.x -= 0.05;
      else if (item.index >= 5 && item.index < 9)
        planeRef.current.position.x += 0.05;
    }
  });

  const animatedEnd = [
    startPoint[0] + (endPoint[0] - startPoint[0]) * progress,
    startPoint[1] + (endPoint[1] - startPoint[1]) * progress,
    startPoint[2] + (endPoint[2] - startPoint[2]) * progress,
  ];

  useLayoutEffect(() => {
    if (isVisible) {
      const showAnimation = setTimeout(() => setIsVisible(false), 1400);
      return () => clearTimeout(showAnimation);
    }
  }, [isVisible]);

  return (
    <group>
      <QuadraticBezierLine
        start={startPoint}
        end={animatedEnd}
        color="BLUE"
        lineWidth={5}
        dashed={false}
        scale={[8, 5, 1]}
      />
      <mesh
        visible={isVisible}
        ref={planeRef}
        position={
          type === "left"
            ? item.index === 5
              ? [0, -4, 0]
              : [-5, 0, 0]
            : item.index === 4
            ? [0, 4, 0]
            : item.index >= 5 && item.index < 9
            ? [-6, 0, 0]
            : [6, 0, 0]
        }
      />
    </group>
  );
};

function Block({ item, previousHash, totalBlocks }) {
  const cubeRef = useRef();
  const texture = useLoader(THREE.TextureLoader, img);

  const [blockData] = useState({
    header: {
      version: "1.0.0",
      previousHash: previousHash || generateRandomHash(),
      merkleRoot: generateRandomHash(),
      timestamp: item.data.purchasedAt || generateRandomTimestamp(),
      difficulty: String(Math.floor(Math.random() * 5) + 1),
      nonce: String(Math.floor(Math.random() * 1000000)),
    },
    hash: generateRandomHash(),
  });

  const [blockProgress, setBlockProgress] = useState(0); // 0 → hidden, 1 → fully visible

  useFrame((_, delta) => {
    cubeRef.current.rotation.y += 0.007;
    if (blockProgress < 1) {
      setBlockProgress((p) => Math.min(1, p + delta * 0.5)); // speed of appearance
    }
  });

  const textProps = {
    font: "/Inter-Bold.woff",
    fontSize: 0.2,
    color: "white",
    anchorX: "center",
    anchorY: "middle",
    "material-toneMapped": false,
  };

  const productNameProps = {
    ...textProps,
    color: "#FFFF00",
    fontSize: 0.25,
    outlineWidth: 0.01,
    outlineColor: "black",
  };

  return (
    <group key={item.id} position={item.position} scale={[blockProgress, blockProgress, blockProgress]}>
      <a.mesh castShadow receiveShadow>
        <Box ref={cubeRef} args={[2, 2, 2]}>
          <meshBasicMaterial attach="material" map={texture} toneMapped={false} />
        </Box>
        <Box args={[3, 3, 3]}>
          <meshPhongMaterial color={"#ddddff"} transparent opacity={0.3} />
        </Box>
        <group position={[0.01, -1.5, 1.5]}>
          <Box position={[0, 2.65, 0.08]} args={[3, 0.7, 0]}>
            <MeshWobbleMaterial color={"blue"} factor={0.1} speed={2} opacity={0.1} transparent />
            <Text position={[0, -0.1, 0.1]} {...textProps}>
              {`Header: ${blockData.header.previousHash}...`}
            </Text>
          </Box>
          <Box position={[0, 1.9, 0.08]} args={[3, 0.7, 0]}>
            <MeshWobbleMaterial color={"blue"} factor={0.1} speed={2} opacity={0.1} transparent />
            <Text position={[0, -0.1, 0.1]} {...textProps}>
              {`Hash: ${blockData.hash.slice(0, 8)}...`}
            </Text>
          </Box>
          <Box position={[0, 1.15, 0.08]} args={[3, 0.7, 0]}>
            <MeshWobbleMaterial color={"blue"} factor={0.1} speed={2} opacity={0.1} transparent />
            <Text position={[0, -0.1, 0.1]} {...productNameProps}>
              {item.data.hash}
            </Text>
          </Box>
          {/* <Box position={[0, 0.4, 0.08]} args={[3, 0.7, 0]}>
            <MeshWobbleMaterial color={"blue"} factor={0.1} speed={2} opacity={0.1} transparent />
            <Text position={[0, -0.1, 0.1]} {...textProps}>
              {generateRandomHash(item.data.purchasedAt)}
            </Text>
          </Box> */}
        </group>
        {/* Show lines only after block fully appeared */}
        {blockProgress === 1 && item.index > 0 && (
          <Line type={"left"} item={item} texture={texture} />
        )}
        {blockProgress === 1 && item.index < totalBlocks - 1 && (
          <Line type={"right"} item={item} texture={texture} />
        )}
      </a.mesh>
    </group>
  );
}

export default Block;
