import React from "react";
import styled from "styled-components/macro";

const Button = styled.button`
  background: ${(props) => (props["data-active"] ? "rgb(88, 92, 92)" : "rgb(58, 146, 146)")};
  border-radius: 10px;
  color:rgb(128, 112, 117);
  margin: 0 1em;
  padding: 1em 1em;
  transition: all 0.3s ease 0s;
  box-shadow: ${(props) =>
    props["data-active"] ? "none" : "0 3px 10px 2pxrgb(47, 118, 119)"};
  width: ${(props) => (props["data-small"] ? "50px" : "150px ")};
  fontsize: 10px;
  border: null;
  &:hover {
    transform: translateY(8px);

    box-shadow: 0 3px 5px 2pxrgb(213, 214, 204);
  }
  button.btn {
    backgroundcolor: "white";
  }
`;
const StyledButton = ({ onClick, children, disabled, small = false }) => {
  console.log("hello", disabled);
  return (
    <Button
      data-active={disabled}
      data-small={small}
      style={{ fontSize: 12, color: "white" }}
      onClick={onClick}
    >
      {children}
    </Button>
  );
};
export default StyledButton;
