// App.js
import React, { Suspense } from "react";
import "./App.css";
import { Provider,useSelector } from "react-redux";
import store from "./redux/Store";
import Divider from "./components/Divider";
import AddProductsComponent from "./components/AddProductsComponent";
import ReceiptContainer from "./components/ReceiptContainer";
import ProductListComponent from "./components/ProductListComponent";
import ShowHistoryComponent from "./components/ShowHistoryComponent";
import { SnackbarProvider } from "notistack";
import Scene from "./components/threeComponents/Scene";


function App() {
const {animationStart,buyed_products} = useSelector(state => state.products);
console.log(typeof(buyed_products));



  return (
    <Suspense fallback={<div>loading...</div>}>
      <Provider store={store}>
        <SnackbarProvider>
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              padding: "20px",
              backgroundColor: "#212529",  // light black background
              minHeight: "100vh",
              overflowY: "auto",           // scroll when content overflows
            }}
          >
            <div className="row" style={{ width: "100%", margin: 0 }}>
              {/* Add Products */}
             
              <div className="col-md-3" style={{ color: "white", padding: "10px" }}>
                 
                <AddProductsComponent />
               
              </div>





              <div className="row">
                {/* Product List Container */}
                <div
                  className="col-12 col-lg-6 col-xl-7"
                  style={{
                    color: "white",
                    padding: "10px",
                    order: 1 // Always first on mobile/tablet
                  }}
                >
                  <ProductListComponent />
                </div>

                {/* Receipt Container */}
                <div
                  className="col-12 col-lg-6 col-xl-5"
                  style={{
                    order: 2, // Always second on mobile/tablet
                  }}
                >
                  <div
                  >

                  <ReceiptContainer/>
                  </div>
                </div>
              </div>


{/* {animationStart ? <div style={{
  width: "100%",          // full width
  height: "50vh",         // height adjusts to viewport
  minHeight: "300px",     // minimum height on small screens
  maxHeight: "600px",     // optional maximum height
}}>
  <Scene />
</div>:<div></div>
} */}


            </div>


{ Object.keys(buyed_products).length > 0 &&   <div style={{ marginTop: "20px", color: "white" }}>
              <ShowHistoryComponent />
            </div>}
          </div>

        </SnackbarProvider>
      </Provider>
    </Suspense>


  );
}

export default App;
