   startAnimation: (state, action) => {
  state.animationStart = true;
  state.animationFinished = false;
  state.currentData = action.payload; // new product
  state.databaseReached = false;
  state.blockchainReached = false;
},
finishAnimation: (state) => {
  state.animationStart = false;
  state.animationFinished = true;

  if (state.pendingProduct) {
    const { id, name, price, quantity, totalPrice, purchasedAt, purchaseId, payementId ,hash,totalStock} = state.pendingProduct;

    // Push a fresh object to buyed_products
    state.buyed_products.push({ id, name, price, quantity, totalPrice, purchasedAt, purchaseId, payementId,hash,totalStock});

    // Push a separate fresh object to blockchain
    state.blockChainDetails.push({ id, name, price, quantity, totalPrice, purchasedAt, purchaseId, payementId,hash,totalStock });

    state.pendingProduct = null;
  }

  state.currentData = [];
},

removeBuyedProduct: (state, action) => {
  const { uniqueKey, keyType = "purchaseId" } = action.payload;

  state.buyed_products = state.buyed_products.filter(
    (product) => product[keyType] !== uniqueKey
  );
},

