import { OrbitControls } from "@react-three/drei";
import { Canvas } from "@react-three/fiber";
import React, { Suspense } from "react";
import Block from "./Block";
import { useSelector } from "react-redux";

const BlockChain = () => {
  const { blockChainDetails } = useSelector((state) => state.products);

  console.log("BLOCKCHAIN DETAILS IN BLOCKCHAINCOMPONET", blockChainDetails);

  const blocks = blockChainDetails.map((product, index) => {
    let position;
    if (index < 5) {
      position = [index * 4, 0, 0];
    } else {
      const offset = index - 5;
      position = [(4 - offset) * 4, -4, 0];
    }
    return {
      id: product.id,
      position,
      data: { ...product },
      index,
    };
  });

  return (
    <Canvas
      camera={{ position: [1, 0, 15], rotation: [0, 0, 70], fov: 50 }}
      style={{
        background: "#212529",
        height: "43vh",
        marginTop: 19,
      }}
    >
      <Suspense fallback={null}>
        <ambientLight intensity={0.5} />
        <directionalLight intensity={0.5} castShadow position={[-8, 16, -8]} />
        <pointLight intensity={0.1} />

       <group
  // center the whole chain horizontally
  position={[
    -(blocks.length - 1) * 2, // shift by half of chain width (block spacing = 4, so 4/2 = 2)
    3,
    4,
  ]}
>
          {blocks.map((item, index) => (
            <Block
              key={item.id}
              item={item}
              previousHash={index > 0 ? blockChainDetails[index - 1].hash : null}
              totalBlocks={blocks.length} // Pass total number of blocks
            />
          ))}
        </group>

        <OrbitControls enableRotate={true} target={[0, 1, 0]} />
        <color args={["#212529"]} attach="background" />
      </Suspense>
    </Canvas>
  );
};

export default BlockChain;