

import * as React from "react";
import { useState } from "react";
import { styled } from "@mui/material/styles";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell, { tableCellClasses } from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import Paper from "@mui/material/Paper";
import Button from "@mui/material/Button";
import TextField from "@mui/material/TextField";
import IconButton from "@mui/material/IconButton";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import SaveIcon from "@mui/icons-material/Save";
import CancelIcon from "@mui/icons-material/Cancel";
import "./Table.css";
import { useSelector, useDispatch } from "react-redux";
import { removeBuyedProduct, updateBuyedProduct } from "./redux/Slice";
import { enqueueSnackbar } from "notistack";

const StyledTableCell = styled(TableCell)(({ theme }) => ({
  [`&.${tableCellClasses.head}`]: {
    backgroundColor: "black",
    color: theme.palette.common.white,
  },
  [`&.${tableCellClasses.body}`]: {
    fontSize: 14,
  },
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  "&:nth-of-type(odd)": {
    backgroundColor: theme.palette.action.hover,
  },
  "&:last-child td, &:last-child th": {
    border: 0,
  },
}));

              const generateDeterministicHash = (obj) => {
                if (!obj) return "0000" + Math.random().toString(16).slice(2, 14);
              
                // Helper to sort object keys recursively
                const sortObject = (input) => {
                  if (typeof input !== "object" || input === null) return input;
                  if (Array.isArray(input)) return input.map(sortObject);
                  return Object.keys(input)
                    .sort()
                    .reduce((acc, key) => {
                      acc[key] = sortObject(input[key]);
                      return acc;
                    }, {});
                };
              
                const sortedObj = sortObject(obj);
                const str = JSON.stringify(sortedObj);
              
                // Simple numeric hash function
                let hash = 0;
                for (let i = 0; i < str.length; i++) {
                  const char = str.charCodeAt(i);
                  hash = (hash << 5) - hash + char;
                  hash |= 0; // Convert to 32-bit integer
                }
              
                return "0000" + Math.abs(hash).toString(16);
              };
// Function to format ISO timestamp to a readable date and time
const formatPurchaseTime = (isoString) => {
  if (!isoString) return "N/A"; // Fallback if no timestamp
  const date = new Date(isoString);
  return date.toLocaleString("en-US", {
    year: "numeric",
    month: "short",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: true,
  }); // Example output: "Mar 12, 2025, 05:00:38 AM"
};

export default function CustomizedTables() {
  const { buyed_products,blockChainHashes } = useSelector((state) => state.products);
  const dispatch = useDispatch();
  
  const [editingRow, setEditingRow] = useState(null);
  const [editedData, setEditedData] = useState({});
 const [verificationResults, setVerificationResults] = useState({});
  const handleEdit = (row, index) => {
    setEditingRow(index);
    setEditedData({ ...row });
  };

  const handleSave = (index,pId) => {
try{
  dispatch(updateBuyedProduct({
      purchaseId: pId,      // must match reducer
      updatedData: editedData // must match reducer
    }));
    setEditingRow(null);
    setEditedData({});

    enqueueSnackbar("Click check button to compare the data in db and blockchain to ensure validity ",{variant:"info"})
}catch(err){
  console.log("update error",err);
  
}

    
  
  };

  const handleCancel = () => {
    setEditingRow(null);
    setEditedData({});
  };

const handleDelete = (index, purchaseId) => {
  console.log("Delete product at index:", index, "with ID:", purchaseId);

  // dispatch to slice
  dispatch(removeBuyedProduct({ uniqueKey: purchaseId, keyType: "purchaseId" }));
};


  const handleInputChange = (field, value) => {
    setEditedData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleCheckHash = (row) => {
const rowToHash = { ...row };
  delete rowToHash.hash;
    // Generate hash for this row
    console.log("GENERATING HASH ROW",rowToHash);
    
    const hash = generateDeterministicHash(rowToHash);
    console.log("TBALE HASH",hash);
    
    const isValid = blockChainHashes.includes(hash);

    // Save result for this row
    setVerificationResults((prev) => ({
      ...prev,
      [row.purchaseId]: isValid,
    }));
    if(verificationResults[row.purchaseId]===true){
      enqueueSnackbar("Data is Valid ",{variant:"success"})
    }else{
           enqueueSnackbar("Data invalid, Mismatches the data in database and blockchain ",{variant:"error"})
    }
  };


  return (
    <><div style={{ width: "95%", margin: "0 auto" }}>
      <div
    style={{
      fontWeight: "bold",
      fontSize: "18px",
      color: "yellow",
      textAlign: "center",
      padding: "8px 0",
      backgroundColor: "black",
    }}
  >
    RDBMS REPRESENTATION
  </div>

  
<TableContainer
  className="table"
  style={{ height: "47vh", width: "100%", margin: "0 auto" }}
  component={Paper}
>
  <Table size="small" style={{ tableLayout: "fixed" }}>   {/* 👈 Fix layout */}
    <TableHead>
      <TableRow aria-label="customized table">
        <StyledTableCell align="left" style={{ padding: "4px 6px" }}>Id</StyledTableCell>
        <StyledTableCell align="left" style={{ padding: "4px 6px" }}>Purchase Id</StyledTableCell>
        <StyledTableCell style={{ padding: "4px 6px" }}>Product Name</StyledTableCell>
        <StyledTableCell align="right" style={{ padding: "4px 6px" }}>Price(₹)</StyledTableCell>
        <StyledTableCell align="right" style={{ padding: "4px 6px" }}>Stock</StyledTableCell>
        <StyledTableCell align="right" style={{ padding: "4px 6px" }}>Quantity</StyledTableCell>
        <StyledTableCell align="right" style={{ padding: "4px 6px" }}>Total Price(₹)</StyledTableCell>
        <StyledTableCell align="right" style={{ padding: "4px 6px" }}>Payment Id</StyledTableCell>
        <StyledTableCell align="right" style={{ padding: "4px 6px" }}>Time</StyledTableCell>
        <StyledTableCell align="right" style={{ padding: "4px 6px" }}>Status</StyledTableCell>

        {/* ✅ Merge two headers into one */}
        <StyledTableCell align="center" colSpan={2} style={{ padding: "4px 6px" }}>
          Actions
        </StyledTableCell>
      </TableRow>
    </TableHead>

    <TableBody>
      {buyed_products.length > 0 &&
        buyed_products.map((row, index) => (
          <StyledTableRow key={row.id}>
            <StyledTableCell align="left" style={{ padding: "4px 6px" }}>
              {index + 1}
            </StyledTableCell>

            <StyledTableCell align="left" style={{ padding: "4px 6px" }}>
              {editingRow === index ? (
                <TextField
                  size="small"
                  value={editedData.purchaseId || ""}
                  onChange={(e) =>
                    handleInputChange("purchaseId", e.target.value)
                  }
                  variant="outlined"
                  fullWidth
                />
              ) : (
                row.purchaseId
              )}
            </StyledTableCell>

            <StyledTableCell style={{ padding: "4px 6px" }}>
              {editingRow === index ? (
                <TextField
                  size="small"
                  value={editedData.name || ""}
                  onChange={(e) => handleInputChange("name", e.target.value)}
                  variant="outlined"
                  fullWidth
                />
              ) : (
                row.name
              )}
            </StyledTableCell>

            <StyledTableCell align="right" style={{ padding: "4px 6px" }}>
              {editingRow === index ? (
                <TextField
                  size="small"
                  type="number"
                  value={editedData.price || ""}
                  onChange={(e) => handleInputChange("price", e.target.value)}
                  variant="outlined"
                  fullWidth
                />
              ) : (
                row.price
              )}
            </StyledTableCell>

            <StyledTableCell align="right" style={{ padding: "4px 6px" }}>
              {editingRow === index ? (
                <TextField
                  size="small"
                  type="number"
                  value={editedData.totalStock || ""}
                  onChange={(e) =>
                    handleInputChange("totalStock", e.target.value)
                  }
                  variant="outlined"
                  fullWidth
                />
              ) : (
                row.totalStock
              )}
            </StyledTableCell>

            <StyledTableCell align="right" style={{ padding: "4px 6px" }}>
              {editingRow === index ? (
                <TextField
                  size="small"
                  type="number"
                  value={editedData.quantity || ""}
                  onChange={(e) =>
                    handleInputChange("quantity", e.target.value)
                  }
                  variant="outlined"
                  fullWidth
                />
              ) : (
                row.quantity
              )}
            </StyledTableCell>

            <StyledTableCell align="right" style={{ padding: "4px 6px" }}>
              {editingRow === index ? (
                <TextField
                  size="small"
                  type="number"
                  value={editedData.totalPrice || ""}
                  onChange={(e) =>
                    handleInputChange("totalPrice", e.target.value)
                  }
                  variant="outlined"
                  fullWidth
                />
              ) : (
                row.totalPrice
              )}
            </StyledTableCell>

            <StyledTableCell align="right" style={{ padding: "4px 6px" }}>
              {editingRow === index ? (
                <TextField
                  size="small"
                  value={editedData.payementId || ""}
                  onChange={(e) =>
                    handleInputChange("payementId", e.target.value)
                  }
                  variant="outlined"
                  fullWidth
                />
              ) : (
                row.payementId
              )}
            </StyledTableCell>

            <StyledTableCell align="right" style={{ padding: "4px 6px" }}>
              {editingRow === index ? (
                <TextField
                  size="small"
                  value={editedData.purchasedAt || ""}
                  onChange={(e) =>
                    handleInputChange("purchasedAt", e.target.value)
                  }
                  variant="outlined"
                  fullWidth
                />
              ) : (
                row.purchasedAt
              )}
            </StyledTableCell>

            <StyledTableCell style={{ padding: "4px 6px" }}>
              <Button
                variant="contained"
                size="small"
                color={
                  verificationResults[row.purchaseId] === true
                    ? "success"
                    : verificationResults[row.purchaseId] === false
                    ? "error"
                    : "primary"
                }
                onClick={() => handleCheckHash(row)}
              >
                {verificationResults[row.purchaseId] === true
                  ? "Valid"
                  : verificationResults[row.purchaseId] === false
                  ? "Invalid"
                  : "Check"}
              </Button>
            </StyledTableCell>

            {/* Update Column */}
            <StyledTableCell align="center" style={{ padding: "4px 6px" }}>
              {editingRow === index ? (
                <div
                  style={{
                    display: "flex",
                    gap: "4px",
                    justifyContent: "center",
                  }}
                >
                  <IconButton
                    color="primary"
                    onClick={() => handleSave(index, row.purchaseId)}
                    size="small"
                    title="Save"
                  >
                    <SaveIcon />
                  </IconButton>
                  <IconButton
                    color="secondary"
                    onClick={handleCancel}
                    size="small"
                    title="Cancel"
                  >
                    <CancelIcon />
                  </IconButton>
                </div>
              ) : (
                <IconButton
                  color="primary"
                  size="small"
                  onClick={() => handleEdit(row, index)}
                >
                  <EditIcon fontSize="small" />
                </IconButton>
              )}
            </StyledTableCell>

            {/* Delete Column */}
            <StyledTableCell align="center" style={{ padding: "4px 6px" }}>
              <IconButton
                color="error"
                size="small"
                onClick={() => handleDelete(index, row.purchaseId)}
                disabled={editingRow === index}
              >
                <DeleteIcon fontSize="small" />
              </IconButton>
            </StyledTableCell>
          </StyledTableRow>
        ))}
    </TableBody>
  </Table>
</TableContainer>



    </div>
    </>
  );
}